<div class="page-header"><div><p class="eyebrow"><?= $organization===null?'ADM Central':'ADM Central · Franquia' ?></p><h1><?= $escape($titleLabel) ?><?= $organization!==null?' — '.$escape((string)$organization['display_name']):'' ?></h1><p>Arquivos privados, organizados por categoria e com histórico de versões.</p></div><div class="page-actions"><?php if($organization!==null):?><a class="button button-secondary" href="<?= $escape($basePath) ?>/admin/organizations/<?= (int)$organization['id'] ?>"><i class="fa-solid fa-arrow-left"></i> Voltar à franquia</a><?php endif;?></div></div>
